const articleTranslations:Record<Exclude<Locale,"en">,Article>={
 fr:{tag:"MÉTHODE",title:"Premier achat LoloBuy : guide pratique avant de payer",description:"Une lecture fondée sur les faits pour comprendre le parcours public de LoloBuy, préparer un lien produit et mieux vérifier avant paiement.",note:"Note factuelle : ce guide s’appuie sur la page d’accueil publique de LoloBuy et ses étapes visibles, vérifiées le 02 septembre 2026. Il ne promet ni prix, ni délai, ni résultat douanier, ni qualité.",sections:[
 {heading:"Commencez par la tâche que la plateforme affiche",paragraphs:["La mauvaise décision commence souvent par un slogan plutôt que par une tâche. La page publique de LoloBuy invite à rechercher avec un lien ou un nom de produit, et montre aussi une estimation du fret et le transfert. Cela indique un parcours : trouver l’article, le faire entrer dans le flux d’entrepôt, puis choisir son envoi.","Traitez le lien produit comme une preuve et non comme un ordre d’achat. Il montre un titre, des photos, une variante et un prix à un instant, mais pas nécessairement le stock réel, l’expédition du vendeur ou les choix finaux pour votre pays. Gardez le lien, cherchez aussi le nom et comparez les détails visibles.","Le parcours public place le paiement de commande, puis l’inspection et le stockage en entrepôt, avant le contrôle et l’envoi groupé. Séparez donc les faits du produit, ceux de l’entrepôt et ceux du colis sortant. Une capture et une estimation ne constituent pas un coût final."]},
 {heading:"Lisez l’annonce comme si vous deviez l’expliquer plus tard",paragraphs:["Commencez par l’identité : nom, couleur, taille ou version sélectionnée. Vérifiez que la photo correspond au texte et que les mesures indiquent bien ce qu’elles mesurent. Notez simplement la variante choisie et les dimensions. Cette trace évite de comparer la photo d’une offre avec le menu d’une autre.","Distinguez le prix de l’article du coût d’une commande terminée. Le parcours public mentionne le paiement du produit et le fret en Chine continentale avant les étapes d’entrepôt et de transfert. N’appelez donc pas un prix produit un total si le paiement ne détaille pas toutes les autres sommes.","Les photos d’annonce sont une présentation du vendeur. LoloBuy annonce des photos gratuites de contrôle qualité à l’étape entrepôt ; elles sont utiles sans être une garantie. Préparez avant paiement une liste précise : variante, couleur, couture, quincaillerie, étiquette ou compatibilité selon l’article."]},
 {heading:"Utilisez l’entrepôt et le QC pour décider, pas pour vous rassurer",paragraphs:["La page publique parle d’inspection en entrepôt, de photos QC gratuites et de 180 jours de stockage gratuit. Lisez ces éléments étroitement : ils offrent un moment pour revoir l’article et annoncent une période de stockage. Ils ne résolvent pas chaque doute depuis une photo et les conditions visibles lors de commande restent décisives.","Les photos QC sont les plus utiles face à votre liste préparée. Vérifiez d’abord couleur, étiquette de taille, quantité et type. Regardez ensuite les détails importants. Ne cherchez pas des défauts impossibles à évaluer, mais ne déclarez pas non plus l’article parfait parce que l’image paraît nette. En cas d’incertitude, arrêtez-vous.","Le stockage sert aussi à planifier. Notez article, arrivée attendue, statut, point QC et appartenance au colis. La page dit que des biens sélectionnés peuvent être soumis comme un seul colis ; c’est une possibilité, non une obligation de tout regrouper. Le choix dépend des options réelles, de l’article et du pays."]},
 {heading:"Comprenez les estimations de fret sans les transformer en garantie",paragraphs:["LoloBuy affiche un accès à l’estimation de fret. Utilisez-le tôt, mais comme estimation. Le colis final peut changer selon le pays, la ligne disponible, le poids, la taille, les restrictions et le contenu réel. Consignez les hypothèses : destination, nombre d’articles et mesures encore inconnues.","Deux erreurs sont fréquentes : comparer seulement le prix produit, ou traiter une première estimation comme une promesse. Comparez plutôt les mêmes articles, le même pays et la même date. Indiquez si une option n’est visible qu’à ce moment. Si une ligne n’est pas proposée, ne supposez pas qu’elle le sera plus tard.","L’envoi groupé appelle la même prudence. La page décrit la sélection de biens d’entrepôt dans un seul colis. Cela peut convenir lorsque tout est prêt et que les options sont revues, mais ce n’est pas automatiquement moins cher, plus rapide ou plus sûr. Demandez ce que montre l’estimation pour ces articles et ce pays réels."]},
 {heading:"Une séquence simple pour une première commande",paragraphs:["Choisissez un article clairement identifié ; conservez le lien et la variante ; notez les faits visibles ; consultez les outils de fret liés au pays ; définissez la liste QC avant paiement ; puis relisez les preuves d’entrepôt et les options de colis disponibles. Cette séquence calme remplace les décisions émotionnelles par des vérifications successives.","Gardez enfin des promesses plus petites que vos preuves. Vous pouvez dire que la page publique montre recherche par lien ou nom, transfert, estimation de fret, inspection et stockage, photos QC gratuites, 180 jours annoncés et soumission d’articles sélectionnés dans un colis. N’en déduisez pas délai fixe, résultat douanier, route ou coût final garanti."]}]},
 de:{tag:"ABLAUF",title:"LoloBuy-Erstbestellung: praktischer Leitfaden vor dem Bezahlen",description:"Eine faktenbasierte Lesart des öffentlichen LoloBuy-Ablaufs, um Produktlink und Prüfungen vor der Zahlung besser vorzubereiten.",note:"Faktenhinweis: Grundlage sind die öffentliche LoloBuy-Startseite und die sichtbaren Ablaufbezeichnungen, geprüft am 02. September 2026. Keine Zusage zu Preis, Laufzeit, Zoll oder Qualität.",sections:[
 {heading:"Beginnen Sie mit der Aufgabe, die die Plattform zeigt",paragraphs:["Schlechte Kaufentscheidungen beginnen oft mit einem Slogan statt mit einer Aufgabe. Die öffentliche LoloBuy-Seite fordert einen Produktlink oder Produktnamen und zeigt Frachtkalkulation sowie Weiterleitung. Damit wird klar: Zuerst Artikel prüfen, dann Lagerablauf verstehen und schließlich Versand wählen.","Behandeln Sie einen Link als Beleg, nicht als Kaufanweisung. Er zeigt Titel, Fotos, Variante und Preis zu einem Zeitpunkt, aber nicht zwingend Bestand, Versandbereitschaft oder passende Endoptionen für Ihr Land. Bewahren Sie den Link auf, suchen Sie zusätzlich den Namen und vergleichen Sie die sichtbaren Angaben.","Die öffentliche Abfolge nennt erst Bestellzahlung, dann Qualitätsprüfung und Lagerung, danach Kontrolle und gebündelte Lieferung. Trennen Sie daher Produktfakten, Lagerfakten und Fakten des ausgehenden Pakets. Ein Screenshot plus Schätzung ist kein Endpreis."]},
 {heading:"Lesen Sie ein Angebot so, dass Sie es später erklären können",paragraphs:["Starten Sie mit der Identität: Bezeichnung, gewählte Farbe, Größe oder Version. Prüfen Sie, ob Foto und Text dieselbe Variante meinen und was Maße tatsächlich beschreiben. Eine knappe Notiz zu Variante und Maßen verhindert, dass ein Foto eines Angebots mit einem Variantenmenü eines anderen verglichen wird.","Trennen Sie Artikelpreis und vollständige Bestellung. Der öffentliche Ablauf nennt Produktzahlung und Fracht innerhalb Chinas vor Lager- und Weiterleitungsstufen. Nennen Sie einen Produktpreis deshalb nicht Gesamtbetrag, wenn der Checkout nicht jede weitere Gebühr ausweist. Versprechen Sie keine Lieferung oder Zollentscheidung aus einem Listing.","Angebotsbilder sind Verkäuferdarstellung. LoloBuy bewirbt kostenlose QC-Bilder im Lager; sie sind nützlich, aber keine Garantie. Legen Sie vorher eine konkrete Prüfliste an: Variante, Farbe, Naht, Beschläge, Etikett oder Kompatibilität. Für Elektronik sind Modell, Stecker, Zustand und Kompatibilität wichtiger als ein schönes Bild."]},
 {heading:"Nutzen Sie Lager und QC für Entscheidungen, nicht zur Beruhigung",paragraphs:["Die öffentliche Seite nennt Lagerprüfung, kostenlose QC-Bilder und 180 Tage kostenlose Lagerung. Lesen Sie das eng: Es gibt einen Lagerzeitpunkt zum erneuten Prüfen und ein beworbenes Lagerfenster. Fotos lösen nicht jede Frage, und die live sichtbaren Bedingungen beim Bestellen sind maßgeblich.","QC-Bilder funktionieren mit Ihrer vorherigen Checkliste. Prüfen Sie zunächst Farbe, Größenetikett, Menge und Grundtyp, dann die wirklich wichtigen Details. Suchen Sie nicht nach mikroskopischen Fehlern, die ein Foto nicht zeigen kann; nennen Sie einen Artikel aber auch nicht perfekt, nur weil das Bild ordentlich wirkt. Bei Unklarheit pausieren Sie.","Lagerung ist Planungshilfe. Notieren Sie Artikel, erwartete Ankunft, Status, QC-Punkt und Paketzuordnung. Die Seite sagt, ausgewählte Lagerwaren könnten als ein Paket eingereicht werden. Das ist eine Option, keine Regel. Die richtige Wahl hängt von Live-Optionen, Artikelart und Ziel ab."]},
 {heading:"Frachtkalkulationen verstehen, ohne sie zur Garantie zu machen",paragraphs:["LoloBuy zeigt einen Zugang zur Frachtkalkulation. Nutzen Sie ihn früh, aber als Schätzung. Das Endpaket kann je nach Ziel, verfügbarer Linie, Gewicht, Abmessungen, Einschränkungen und Inhalt anders aussehen. Notieren Sie Annahmen: Land, ungefähre Artikelzahl und unbekannte Maße.","Häufige Fehler sind der Vergleich nur des Artikelpreises und die Behandlung einer frühen Schätzung als Zusage. Vergleichen Sie stattdessen dieselben Artikel, dasselbe Ziel und dasselbe Datum. Halten Sie fest, wenn eine Option nur gerade sichtbar ist. Nicht verfügbare Linien sollten nicht als später sicher dargestellt werden.","Auch Sammelversand braucht diese Sprache. Die Seite beschreibt ausgewählte Lagerwaren in einem Paket. Das kann passen, wenn Artikel bereit sind und Live-Optionen geprüft wurden; es ist aber nicht automatisch billiger, schneller oder sicherer. Entscheidend ist die aktuelle Schätzung für diese Artikel und dieses Ziel."]},
 {heading:"Eine einfache Reihenfolge für die erste Bestellung",paragraphs:["Wählen Sie einen eindeutig bestimmten Artikel, speichern Sie Link und Variante, notieren Sie sichtbare Fakten, prüfen Sie zielabhängige Frachtwerkzeuge, bestimmen Sie die QC-Liste vor Zahlung und sehen Sie dann Lagerbelege sowie Live-Paketoptionen an. Diese absichtlich nüchterne Reihenfolge ersetzt Impulse durch nachvollziehbare Prüfungen.","Machen Sie Ihre Zusagen kleiner als Ihre Belege. Korrekt ist: Die öffentliche Seite zeigt Suche nach Link oder Name, Weiterleitung, Frachtschätzung, Lagerprüfung und -lagerung, kostenlose QC-Bilder, beworbene 180 Tage sowie die Option eines Sammelpakets. Daraus folgen weder feste Laufzeit noch Zoll-, Routen- oder Endkostengarantie."]}]},
 es:{tag:"PROCESO",title:"Primer pedido en LoloBuy: guía práctica antes de pagar",description:"Una lectura basada en hechos del flujo público de LoloBuy para preparar un enlace de producto y revisar mejor antes del pago.",note:"Nota factual: esta guía se basa en la página pública de LoloBuy y en las etapas visibles, comprobadas el 02 de septiembre de 2026. No promete precio, plazo, aduana ni calidad.",sections:[
 {heading:"Empieza por la tarea que muestra la plataforma",paragraphs:["Una mala decisión suele empezar por un eslogan y no por una tarea. La página pública de LoloBuy pide un enlace o nombre de producto y muestra estimación de flete y reenvío. Eso revela el recorrido: localizar el artículo, entender el almacén y después decidir cómo se enviará.","Trata un enlace como prueba, no como una instrucción de compra. Puede mostrar título, fotos, variante y precio en un momento, pero no necesariamente stock, despacho del vendedor u opciones finales para tu destino. Guarda el enlace, busca también el nombre y compara la información que ves.","El flujo público coloca el pago, después inspección y almacenamiento, y luego control y entrega combinada. Separa hechos del producto, del almacén y del paquete saliente. Una captura y una estimación no son un coste final."]},
 {heading:"Lee el anuncio como si luego tuvieras que explicarlo",paragraphs:["Empieza por la identidad: nombre, color, talla o versión elegida. Confirma que la foto corresponde al texto y qué significan las medidas. Una nota breve sobre variante y dimensiones evita comparar la foto de un anuncio con el menú de variantes de otro.","Separa precio del producto y coste de un pedido terminado. El flujo público menciona pago del producto y flete dentro de China antes del almacén y reenvío. No llames total al precio del artículo si el checkout no identifica los demás cargos. Tampoco prometas entrega o aduana desde un anuncio.","Las fotos del anuncio son presentación del vendedor. LoloBuy anuncia fotos gratuitas de QC en almacén; son útiles, pero no una garantía. Antes de pagar prepara una lista concreta: variante, color, costuras, herrajes, etiqueta o compatibilidad. Para electrónica importan más modelo, enchufe, estado y compatibilidad."]},
 {heading:"Usa almacén y QC para decidir, no para tranquilizarte",paragraphs:["La página pública menciona inspección de almacén, fotos QC gratuitas y 180 días de almacenamiento gratuito. Léelo de forma limitada: hay una ocasión de revisar el artículo y un periodo anunciado. Una foto no resuelve toda duda y las condiciones visibles al pedir son las que cuentan.","Las fotos QC sirven mejor frente a tu lista previa. Comprueba primero color, etiqueta de talla, cantidad y tipo básico, y luego los detalles importantes. No busques defectos microscópicos que una foto no puede evaluar, pero tampoco declares perfecto un artículo porque la imagen parezca limpia. Si no está claro, pausa.","El almacenamiento también ayuda a planificar. Anota artículo, llegada prevista, estado, punto QC y si pertenece al mismo paquete. La página dice que artículos seleccionados pueden enviarse como un solo paquete; es una opción, no una regla. La decisión depende de opciones reales, tipo de artículo y destino."]},
 {heading:"Entiende las estimaciones de flete sin convertirlas en garantía",paragraphs:["LoloBuy muestra acceso a una estimación de flete. Úsala pronto, pero como estimación. El paquete final puede variar por destino, línea disponible, peso, tamaño, restricciones y contenido real. Registra las hipótesis: país, cantidad aproximada y medidas desconocidas.","Dos errores son comparar solo el precio del producto y tratar una estimación temprana como promesa. Compara los mismos artículos, el mismo destino y la misma fecha. Indica si una opción solo aparece en ese momento. Si una línea no se ofrece, no supongas que estará disponible después.","La entrega combinada requiere la misma prudencia. La página describe seleccionar bienes del almacén en un solo paquete. Puede tener sentido cuando todo está listo y se revisan opciones, pero no es automáticamente más barata, rápida o segura. Pregunta qué muestra la estimación actual para esos artículos y ese país."]},
 {heading:"Una secuencia sencilla para el primer pedido",paragraphs:["Elige un artículo bien identificado; guarda enlace y variante; apunta los hechos visibles; revisa herramientas de flete según destino; decide tu lista QC antes de pagar; y después revisa las pruebas de almacén y opciones de paquete activas. Esta secuencia tranquila sustituye decisiones emocionales por comprobaciones.","Mantén tus promesas por debajo de tus pruebas. Puedes decir que la página pública muestra búsqueda por enlace o nombre, reenvío, estimación de flete, inspección y almacenamiento, fotos QC gratuitas, 180 días anunciados y la opción de un paquete combinado. No convierte esos hechos en plazo, aduana, ruta o coste final garantizado."]}]},
 it:{tag:"PROCESSO",title:"Primo ordine LoloBuy: guida pratica prima del pagamento",description:"Una lettura basata sui fatti del flusso pubblico LoloBuy per preparare un link prodotto e controllare meglio prima di pagare.",note:"Nota sui fatti: guida basata sulla homepage pubblica LoloBuy e sulle fasi visibili, controllate il 02 settembre 2026. Non promette prezzi, tempi, dogana o qualità.",sections:[
 {heading:"Parti dal compito mostrato dalla piattaforma",paragraphs:["Una cattiva scelta nasce spesso da uno slogan, non da un compito. La pagina pubblica LoloBuy chiede un link o nome prodotto e mostra stima del trasporto e inoltro. Il percorso è quindi: trovare l’articolo, comprenderne il passaggio in magazzino e poi scegliere la spedizione.","Considera un link come prova, non come ordine d’acquisto. Può mostrare titolo, foto, variante e prezzo in un momento, ma non necessariamente disponibilità, invio del venditore o opzioni finali per il paese. Conserva il link, cerca anche il nome e confronta le informazioni visibili.","Il flusso pubblico indica pagamento dell’ordine, poi ispezione e deposito in magazzino, quindi controllo e consegna combinata. Separa perciò fatti del prodotto, del magazzino e del pacco in uscita. Una schermata e una stima non sono un costo finale."]},
 {heading:"Leggi l’inserzione come se dovessi spiegarla più tardi",paragraphs:["Inizia dall’identità: nome, colore, taglia o versione selezionata. Verifica che foto e testo indichino la stessa variante e cosa misurino davvero le dimensioni. Una breve nota su variante e misure evita di confrontare la foto di un’inserzione con il menu di un’altra.","Separa il prezzo dell’articolo dal costo di un ordine completato. Il flusso pubblico cita pagamento del prodotto e trasporto in Cina prima del magazzino e dell’inoltro. Non chiamare totale un prezzo prodotto se il checkout non identifica gli altri importi. Non promettere consegna o dogana da un’inserzione.","Le immagini dell’inserzione sono presentazione del venditore. LoloBuy pubblicizza foto QC gratuite in magazzino: sono utili, non una garanzia. Prima di pagare prepara una lista precisa: variante, colore, cuciture, ferramenta, etichetta o compatibilità. Per elettronica contano modello, spina, stato e compatibilità."]},
 {heading:"Usa magazzino e QC per decidere, non per rassicurarti",paragraphs:["La pagina pubblica cita ispezione in magazzino, foto QC gratuite e 180 giorni di deposito gratuito. Leggi questi elementi in modo limitato: esiste un momento per rivedere l’articolo e un periodo pubblicizzato. Una foto non risolve ogni dubbio e le condizioni visibili all’ordine restano decisive.","Le foto QC rendono al meglio con la lista preparata. Controlla prima colore, etichetta della taglia, quantità e tipo, poi i dettagli importanti. Non cercare difetti microscopici impossibili da valutare in foto, ma non dichiarare perfetto un articolo perché l’immagine è ordinata. Se non è chiaro, fermati.","Il deposito è anche uno strumento di pianificazione. Annota articolo, arrivo previsto, stato, punto QC e pacco. La pagina dice che beni selezionati possono essere inviati come un solo pacco; è un’opzione, non un obbligo. La scelta dipende da opzioni reali, articolo e destinazione."]},
 {heading:"Comprendi le stime di trasporto senza farne una garanzia",paragraphs:["LoloBuy mostra un accesso alla stima del trasporto. Usalo presto, ma come stima. Il pacco finale può cambiare per destinazione, linea disponibile, peso, dimensioni, restrizioni e contenuto. Registra le ipotesi: paese, quantità approssimativa e misure sconosciute.","Gli errori comuni sono confrontare solo il prezzo prodotto e trattare una stima iniziale come promessa. Confronta gli stessi articoli, la stessa destinazione e la stessa data. Segnala se un’opzione è visibile solo in quel momento. Se una linea non è offerta, non supporre che lo sarà in seguito.","La consegna combinata richiede la stessa cautela. La pagina descrive la selezione di beni di magazzino in un pacco. Può essere sensata quando tutto è pronto e le opzioni sono state viste, ma non è automaticamente più economica, rapida o sicura. Conta ciò che mostra la stima per quegli articoli e quel paese."]},
 {heading:"Una sequenza semplice per il primo ordine",paragraphs:["Scegli un articolo identificato con chiarezza; salva link e variante; annota i fatti visibili; controlla strumenti di trasporto per destinazione; definisci la lista QC prima del pagamento; poi rivedi prove di magazzino e opzioni di pacco. Questa sequenza sostituisce le decisioni emotive con controlli tracciabili.","Mantieni le promesse più piccole delle prove. Puoi affermare che la pagina pubblica mostra ricerca per link o nome, inoltro, stima del trasporto, ispezione e deposito, foto QC gratuite, 180 giorni pubblicizzati e un pacco combinato. Non ne derivano tempi, dogana, rotta o costo finale garantiti."]}]},
 pt:{tag:"PROCESSO",title:"Primeira encomenda LoloBuy: guia prático antes de pagar",description:"Uma leitura baseada em factos do fluxo público da LoloBuy para preparar um link de produto e verificar melhor antes do pagamento.",note:"Nota factual: este guia baseia-se na página pública da LoloBuy e nas etapas visíveis, verificadas em 02 de setembro de 2026. Não promete preço, prazo, alfândega ou qualidade.",sections:[
 {heading:"Comece pela tarefa que a plataforma mostra",paragraphs:["Uma decisão fraca começa muitas vezes por um slogan e não por uma tarefa. A página pública da LoloBuy pede um link ou nome de produto e mostra estimativa de frete e reencaminhamento. O percurso é: encontrar o artigo, compreender o fluxo de armazém e depois escolher o envio.","Trate o link como prova, não como instrução de compra. Pode mostrar título, fotos, variante e preço num momento, mas não necessariamente stock, envio do vendedor ou opções finais para o país. Guarde o link, pesquise também o nome e compare a informação visível.","O fluxo público coloca o pagamento, depois inspeção e armazenamento, e por fim controlo e entrega combinada. Separe factos do produto, do armazém e da encomenda de saída. Uma captura e uma estimativa não são um custo final."]},
 {heading:"Leia o anúncio como quem poderá explicá-lo depois",paragraphs:["Comece pela identidade: nome, cor, tamanho ou versão escolhida. Confirme que a foto corresponde ao texto e o que as medidas significam. Uma nota curta sobre variante e dimensões evita comparar a imagem de um anúncio com o menu de variantes de outro.","Separe preço do artigo e custo de uma encomenda terminada. O fluxo público menciona pagamento do produto e frete na China antes do armazém e reencaminhamento. Não chame total ao preço do produto se o checkout não identificar os outros valores. Não prometa entrega ou alfândega a partir de um anúncio.","As fotos do anúncio são apresentação do vendedor. A LoloBuy anuncia fotos QC gratuitas no armazém; são úteis, não garantia. Antes de pagar, prepare uma lista concreta: variante, cor, costuras, ferragens, etiqueta ou compatibilidade. Em eletrónica, modelo, ficha, estado e compatibilidade contam mais do que uma foto bonita."]},
 {heading:"Use armazém e QC para decidir, não para se tranquilizar",paragraphs:["A página pública refere inspeção no armazém, fotos QC gratuitas e 180 dias de armazenamento gratuito. Leia de forma limitada: existe uma oportunidade para rever o artigo e um período anunciado. Uma foto não resolve cada dúvida e as condições visíveis no pedido são as que importam.","As fotos QC funcionam melhor contra a lista preparada. Verifique primeiro cor, etiqueta de tamanho, quantidade e tipo básico; depois, os detalhes importantes. Não procure defeitos microscópicos impossíveis de avaliar numa foto, mas não declare perfeito um artigo porque a imagem parece limpa. Se não estiver claro, pare.","O armazenamento é também planeamento. Registe artigo, chegada esperada, estado, ponto QC e pacote. A página diz que bens selecionados podem ser enviados como uma só encomenda; é uma opção, não uma regra. A escolha depende das opções reais, do tipo de artigo e do destino."]},
 {heading:"Compreenda estimativas de frete sem as tornar garantias",paragraphs:["A LoloBuy mostra acesso a estimativa de frete. Use-a cedo, mas como estimativa. A encomenda final pode variar por destino, linha disponível, peso, dimensão, restrições e conteúdo. Registe pressupostos: país, quantidade aproximada e medidas desconhecidas.","Erros comuns são comparar apenas o preço do produto e tratar uma estimativa inicial como promessa. Compare os mesmos artigos, o mesmo destino e a mesma data. Indique se uma opção aparece só naquele momento. Se uma linha não é oferecida, não suponha que estará disponível mais tarde.","A entrega combinada merece igual cuidado. A página descreve selecionar bens do armazém num só pacote. Pode fazer sentido quando tudo está pronto e as opções foram revistas, mas não é automaticamente mais barata, rápida ou segura. Importa o que a estimativa mostra para aqueles artigos e aquele destino."]},
 {heading:"Uma sequência simples para a primeira encomenda",paragraphs:["Escolha um artigo claramente identificado; guarde link e variante; anote factos visíveis; consulte ferramentas de frete por destino; defina a lista QC antes de pagar; e reveja depois provas de armazém e opções de pacote. Esta sequência calma troca decisões emocionais por verificações rastreáveis.","Mantenha promessas menores que as provas. Pode dizer que a página pública mostra pesquisa por link ou nome, reencaminhamento, estimativa de frete, inspeção e armazenamento, fotos QC gratuitas, 180 dias anunciados e opção de pacote combinado. Não transforme isso em prazo, alfândega, rota ou custo final garantido."]}]},
 nl:{tag:"WERKWIJZE",title:"Eerste LoloBuy-bestelling: praktische gids vóór betaling",description:"Een feitelijke lezing van de openbare LoloBuy-stappen om een productlink voor te bereiden en vóór betaling beter te controleren.",note:"Feitennoot: deze gids is gebaseerd op de openbare LoloBuy-homepage en zichtbare stappen, gecontroleerd op 02 september 2026. Geen belofte over prijs, levertijd, douane of kwaliteit.",sections:[
 {heading:"Begin met de taak die het platform laat zien",paragraphs:["Een slechte aankoopbeslissing begint vaak met een slogan in plaats van een taak. De openbare LoloBuy-pagina vraagt om een productlink of -naam en toont vrachtschatting en doorsturen. De route is dus: artikel vinden, magazijnstroom begrijpen en daarna verzending kiezen.","Zie een link als bewijs, niet als koopopdracht. Hij toont op één moment titel, foto’s, variant en prijs, maar niet altijd voorraad, verzending door de verkoper of passende eindopties voor je land. Bewaar de link, zoek ook op de naam en vergelijk de zichtbare informatie.","De openbare volgorde noemt eerst betaling, daarna kwaliteitscontrole en opslag, en vervolgens controle en gecombineerde levering. Scheid daarom productfeiten, magazijnfeiten en feiten over het uitgaande pakket. Een schermafbeelding plus schatting is geen eindbedrag."]},
 {heading:"Lees de listing alsof je die later moet uitleggen",paragraphs:["Begin met identiteit: naam, gekozen kleur, maat of versie. Controleer of foto en tekst dezelfde variant tonen en wat maten werkelijk betekenen. Een korte notitie over variant en afmetingen voorkomt dat je een foto van de ene listing vergelijkt met het variantenmenu van een andere.","Scheid artikelprijs van kosten van een afgeronde bestelling. De openbare route noemt productbetaling en vracht binnen China vóór magazijn en doorsturen. Noem de prijs dus geen totaal als checkout niet alle bedragen benoemt. Beloof geen levering of douane-uitkomst op basis van een listing.","Listingfoto’s zijn presentatie van de verkoper. LoloBuy adverteert gratis QC-foto’s in het magazijn; ze zijn nuttig maar geen garantie. Maak vóór betaling een concrete lijst: variant, kleur, naden, hardware, label of compatibiliteit. Voor elektronica zijn model, stekker, staat en compatibiliteit vaak belangrijker dan een fraaie foto."]},
 {heading:"Gebruik magazijn en QC om te beslissen, niet om gerust te zijn",paragraphs:["De openbare pagina noemt magazijninspectie, gratis QC-foto’s en 180 dagen gratis opslag. Lees dit beperkt: er is een magazijnmoment om het artikel opnieuw te bekijken en een geadverteerde opslagperiode. Een foto lost niet elke vraag op; de voorwaarden die bij de bestelling zichtbaar zijn, zijn leidend.","QC-foto’s werken het best naast je voorbereide lijst. Controleer eerst kleur, maatlabel, aantal en basistype, daarna belangrijke details. Zoek niet naar microscopische fouten die een foto niet kan beoordelen, maar noem een artikel ook niet perfect omdat de foto er netjes uitziet. Bij onduidelijkheid pauzeer je.","Opslag is ook planning. Noteer artikel, verwachte aankomst, status, QC-punt en pakket. De pagina zegt dat geselecteerde magazijngoederen als één pakket kunnen worden ingediend; dat is een optie, geen regel. De keuze hangt af van live opties, artikeltype en bestemming."]},
 {heading:"Begrijp vrachtschattingen zonder ze een garantie te maken",paragraphs:["LoloBuy toont een ingang voor vrachtschatting. Gebruik die vroeg, maar als schatting. Het definitieve pakket kan verschillen door bestemming, beschikbare lijn, gewicht, afmetingen, beperkingen en inhoud. Noteer aannames: land, geschat aantal artikelen en onbekende maten.","Twee fouten zijn alleen de artikelprijs vergelijken en een vroege schatting als belofte zien. Vergelijk dezelfde artikelen, bestemming en datum. Noteer of een optie alleen op dat moment zichtbaar is. Is een lijn niet beschikbaar, doe dan niet alsof zij later zeker beschikbaar is.","Ook gecombineerde levering vraagt dezelfde voorzichtigheid. De pagina beschrijft geselecteerde magazijngoederen in één pakket. Dat kan passen wanneer alles klaar is en opties zijn bekeken, maar is niet automatisch goedkoper, sneller of veiliger. Kijk wat de actuele schatting toont voor deze artikelen en deze bestemming."]},
 {heading:"Een eenvoudige volgorde voor een eerste bestelling",paragraphs:["Kies één duidelijk geïdentificeerd artikel; bewaar link en variant; noteer zichtbare feiten; controleer bestemmingsgevoelige vrachttools; bepaal je QC-lijst vóór betaling; en bekijk daarna magazijnbewijs en live pakketopties. Deze rustige volgorde vervangt emotionele keuzes door controleerbare stappen.","Houd beloften kleiner dan bewijs. Je kunt zeggen dat de openbare pagina zoeken op link of naam, doorsturen, vrachtschatting, inspectie en opslag, gratis QC-foto’s, geadverteerde 180 dagen en een gecombineerd pakket toont. Daaruit volgt geen gegarandeerde tijd, douane-uitkomst, route of eindkosten."]}]},
 pl:{tag:"PROCES",title:"Pierwsze zamówienie LoloBuy: praktyczny przewodnik przed płatnością",description:"Oparty na faktach opis publicznego procesu LoloBuy, który pomaga przygotować link produktu i lepiej sprawdzić wszystko przed płatnością.",note:"Uwaga faktyczna: przewodnik oparto na publicznej stronie głównej LoloBuy i widocznych etapach, sprawdzonych 02 września 2026 r. Nie obiecuje ceny, terminu, odprawy ani jakości.",sections:[
 {heading:"Zacznij od zadania pokazanego przez platformę",paragraphs:["Słaba decyzja zakupowa często zaczyna się od hasła, a nie od zadania. Publiczna strona LoloBuy prosi o link lub nazwę produktu i pokazuje wycenę frachtu oraz przekierowanie. Widać więc ciąg: znaleźć przedmiot, zrozumieć etap magazynowy, a potem wybrać wysyłkę.","Traktuj link jako dowód, nie polecenie zakupu. W danej chwili może pokazywać tytuł, zdjęcia, wariant i cenę, ale niekoniecznie stan, wysyłkę sprzedawcy czy końcowe opcje dla kraju. Zachowaj link, wyszukaj także nazwę i porównaj widoczne informacje.","Publiczny proces podaje najpierw płatność, potem kontrolę jakości i magazynowanie, a następnie kontrolę oraz wysyłkę łączoną. Oddziel fakty o produkcie, magazynie i paczce wychodzącej. Zrzut ekranu oraz szacunek nie są ceną końcową."]},
 {heading:"Czytaj ofertę tak, jakbyś miał ją później wyjaśniać",paragraphs:["Zacznij od tożsamości: nazwy, wybranego koloru, rozmiaru lub wersji. Sprawdź, czy zdjęcie odpowiada tekstowi i co faktycznie oznaczają wymiary. Krótka notatka o wariancie i wymiarach zapobiega porównaniu zdjęcia jednej oferty z menu wariantów innej.","Oddziel cenę przedmiotu od kosztu ukończonego zamówienia. Publiczny proces wspomina płatność za produkt i fracht w Chinach przed magazynem i przekierowaniem. Nie nazywaj ceny produktu sumą, jeśli checkout nie pokazuje pozostałych opłat. Nie obiecuj dostawy ani odprawy na podstawie oferty.","Zdjęcia oferty są prezentacją sprzedawcy. LoloBuy reklamuje bezpłatne zdjęcia QC w magazynie; są przydatne, lecz nie stanowią gwarancji. Przed płatnością przygotuj konkretną listę: wariant, kolor, szwy, okucia, etykieta lub zgodność. W elektronice ważne są model, wtyczka, stan i kompatybilność."]},
 {heading:"Korzystaj z magazynu i QC do decyzji, nie do uspokojenia",paragraphs:["Publiczna strona wymienia kontrolę w magazynie, bezpłatne zdjęcia QC i 180 dni darmowego przechowywania. Czytaj to wąsko: istnieje moment magazynowy na ponowne oględziny oraz reklamowany okres. Zdjęcie nie rozwiąże każdego problemu, a warunki widoczne przy zamówieniu są rozstrzygające.","Zdjęcia QC najlepiej działają z przygotowaną listą. Najpierw sprawdź kolor, etykietę rozmiaru, liczbę i typ, potem kluczowe szczegóły. Nie szukaj mikrowad, których zdjęcie nie pozwala ocenić, ale nie uznawaj przedmiotu za idealny tylko dlatego, że obraz wygląda schludnie. Gdy nie ma jasności, zatrzymaj się.","Przechowywanie to również planowanie. Zapisz przedmiot, oczekiwane przybycie, status, punkt QC i paczkę. Strona mówi, że wybrane towary magazynowe można zgłosić jako jedną paczkę; to opcja, nie zasada. Wybór zależy od opcji na żywo, przedmiotu i kraju."]},
 {heading:"Rozumiej wyceny frachtu, nie zmieniając ich w gwarancję",paragraphs:["LoloBuy pokazuje wejście do wyceny frachtu. Używaj go wcześnie, ale jako wyceny. Końcowa paczka może się różnić przez kraj, dostępną linię, wagę, wymiary, ograniczenia i rzeczywistą zawartość. Zapisuj założenia: kraj, liczbę produktów i nieznane wymiary.","Częste błędy to porównywanie tylko ceny produktu oraz uznanie wczesnej wyceny za obietnicę. Porównuj te same przedmioty, ten sam kraj i tę samą datę. Zaznacz, gdy opcja jest widoczna tylko w danej chwili. Jeśli linia nie jest oferowana, nie zakładaj, że pojawi się później.","Wysyłka łączona wymaga tej samej ostrożności. Strona opisuje wybrane towary magazynowe w jednej paczce. Może mieć sens, gdy wszystko jest gotowe i opcje sprawdzono, ale nie jest automatycznie tańsza, szybsza ani bezpieczniejsza. Liczy się aktualna wycena dla tych produktów i tego kraju."]},
 {heading:"Prosta kolejność dla pierwszego zamówienia",paragraphs:["Wybierz jasno określony produkt; zapisz link i wariant; zanotuj widoczne fakty; sprawdź narzędzia frachtowe zależne od kraju; ustal listę QC przed płatnością; a potem obejrzyj dowody z magazynu i dostępne opcje paczki. Ta spokojna kolejność zastępuje emocje sprawdzalnymi krokami.","Nie składaj większych obietnic niż dowody. Można powiedzieć, że publiczna strona pokazuje wyszukiwanie linkiem lub nazwą, przekierowanie, wycenę frachtu, inspekcję i magazynowanie, darmowe zdjęcia QC, reklamowane 180 dni i opcję jednej paczki. Nie oznacza to gwarantowanego terminu, odprawy, trasy ani kosztu końcowego."]}]},
 sv:{tag:"FLÖDE",title:"Första LoloBuy-beställningen: praktisk guide före betalning",description:"En faktabaserad läsning av LoloBuys offentliga flöde för att förbereda en produktlänk och kontrollera bättre före betalning.",note:"Faktaanmärkning: guiden bygger på LoloBuys offentliga startsida och synliga steg, kontrollerade 02 september 2026. Den lovar inte pris, leveranstid, tull eller kvalitet.",sections:[
 {heading:"Börja med uppgiften som plattformen visar",paragraphs:["Ett dåligt köpbeslut börjar ofta med en slogan i stället för en uppgift. LoloBuys offentliga sida ber om produktlänk eller produktnamn och visar fraktuppskattning samt vidarebefordran. Flödet är alltså: hitta varan, förstå lagersteget och sedan välja frakt.","Se länken som bevis, inte som köpinstruktion. Den kan visa titel, bilder, variant och pris vid ett tillfälle, men inte nödvändigtvis lagerstatus, säljarens utskick eller slutliga alternativ för landet. Spara länken, sök även på namnet och jämför synlig information.","Det offentliga flödet visar först orderbetalning, sedan kvalitetskontroll och lagring och därefter kontroll samt samlad leverans. Håll därför isär fakta om produkt, lager och utgående paket. En skärmbild och uppskattning är inte en slutkostnad."]},
 {heading:"Läs annonsen som om du senare måste förklara den",paragraphs:["Börja med identitet: namn, vald färg, storlek eller version. Kontrollera att bild och text avser samma variant och vad måtten faktiskt betyder. En kort notering om variant och mått hindrar att du jämför bilden i en annons med variantmenyn i en annan.","Skilj produktpris från kostnaden för en färdig order. Det offentliga flödet nämner produktbetalning och frakt i Kina före lager och vidarebefordran. Kalla inte produktpriset total om kassan inte visar övriga belopp. Lova inte leverans eller tullresultat utifrån en annons.","Annonsbilder är säljarens presentation. LoloBuy marknadsför gratis QC-bilder i lagret; de är användbara men ingen garanti. Gör före betalning en konkret lista: variant, färg, sömmar, beslag, etikett eller kompatibilitet. För elektronik är modell, kontakt, skick och kompatibilitet viktigare än en snygg bild."]},
 {heading:"Använd lager och QC för beslut, inte för att lugna dig",paragraphs:["Den offentliga sidan nämner lagerinspektion, gratis QC-bilder och 180 dagar gratis lagring. Läs det begränsat: det finns ett lagertillfälle att granska varan igen och en annonserad lagringsperiod. Ett foto löser inte varje fråga, och villkoren som visas vid ordern är avgörande.","QC-bilder fungerar bäst mot din förberedda lista. Kontrollera först färg, storleksetikett, antal och grundtyp, sedan viktiga detaljer. Leta inte efter mikroskopiska fel som ett foto inte kan bedöma, men kalla inte heller en vara perfekt för att bilden ser prydlig ut. När något är oklart, pausa.","Lagring är också planering. Skriv upp vara, väntad ankomst, status, QC-punkt och paket. Sidan säger att valda lagervaror kan skickas in som ett paket; det är ett alternativ, inte en regel. Valet beror på livealternativ, varutyp och destination."]},
 {heading:"Förstå fraktuppskattningar utan att göra dem till garantier",paragraphs:["LoloBuy visar en ingång till fraktuppskattning. Använd den tidigt, men som uppskattning. Slutpaketet kan skilja sig beroende på destination, tillgänglig linje, vikt, mått, begränsningar och innehåll. Skriv ner antaganden: land, ungefärligt antal varor och okända mått.","Två vanliga fel är att endast jämföra produktpriset och att behandla en tidig uppskattning som ett löfte. Jämför samma varor, samma destination och samma datum. Notera om ett alternativ endast syns just då. Om en linje inte erbjuds, anta inte att den senare blir tillgänglig.","Samlad leverans kräver samma försiktighet. Sidan beskriver valda lagervaror i ett paket. Det kan passa när allt är klart och alternativen granskats, men är inte automatiskt billigare, snabbare eller säkrare. Avgörande är vad den aktuella uppskattningen visar för dessa varor och denna destination."]},
 {heading:"En enkel ordning för första beställningen",paragraphs:["Välj en tydligt identifierad vara; spara länk och variant; notera synliga fakta; kontrollera destinationsberoende fraktverktyg; bestäm QC-listan före betalning; och granska sedan lagerbevis samt aktiva paketalternativ. Den lugna ordningen ersätter känslostyrda beslut med spårbara kontroller.","Håll löften mindre än bevisen. Du kan säga att den offentliga sidan visar sökning via länk eller namn, vidarebefordran, fraktuppskattning, inspektion och lagring, gratis QC-bilder, annonserade 180 dagar och ett samlat paket. Det innebär inte garanterad tid, tull, rutt eller slutkostnad."]}]}
};

function adapted(locale:Exclude<Locale,"en">):Content {
 const a=articleTranslations[locale]; const base=content[locale]; return {...base,article:a};
}

